package dev.alien.client.scene;
import dev.alien.client.AlienClient;import dev.alien.client.gui.*;import net.minecraft.client.gui.*;
/** Explicit presets plus independent, persisted live shader parameters. */
public final class SceneSkyScreen extends PremiumScreen {
    private final GuiScreen parent;private boolean legacy;public SceneSkyScreen(GuiScreen p){parent=p;}private SceneConfig c(){return AlienClient.get().config().scenes;}
    @Override public void initGui(){fontRendererObj=Ui.font();buttonList.clear();int w=Math.min(520,width-28),x=(width-w)/2,cw=(w-14)/3,step=Math.max(20,Math.min(49,(height-180)/3));String[] names=legacy?new String[]{"Cosmic","BlackHole","Aurora","SnowClouds","Fire","Sunset","Ocean","Storm"}:new String[]{"Galaxy","Aether","Nocturne","Amethyst","Opaline","Rain","Snow","Fire"};for(int i=0;i<names.length;i++)buttonList.add(new SkyCard(10+i,x+i%3*(cw+7),48+i/3*step,cw,step-4,names[i]));int y=height-125;buttonList.add(new Ui.Button(2,x,y,w/2-4,21,"Palette / "+c().palette));buttonList.add(new Ui.Button(3,x+w/2+4,y,w/2-4,21,legacy?"Video sky styles":"Earlier Alien skies"));buttonList.add(new Ui.Slider(30,x,y+27,w/2-4,23,"Animation speed",0,3,.05f,c().skySpeed,v->c().skySpeed=v));buttonList.add(new Ui.Slider(31,x+w/2+4,y+27,w/2-4,23,"Liveliness",0,1,.05f,c().skyLiveliness,v->c().skyLiveliness=v));buttonList.add(new Ui.Slider(32,x,y+55,w/2-4,23,"Breathing speed",0,3,.05f,c().skyBreathing,v->c().skyBreathing=v));buttonList.add(new Ui.Button(4,x+w/2+4,y+55,w/2-4,23,"Sky OFF"));buttonList.add(new Ui.Button(5,x,height-30,w/2-4,22,"Reset sky controls"));buttonList.add(new Ui.Button(0,x+w/2+4,height-30,w/2-4,22,"Done"));}
    @Override protected void actionPerformed(GuiButton b){if(b.id==0){AlienClient.get().save();mc.displayGuiScreen(parent);return;}if(b.id>=10&&b.id<18){c().sky=b.displayString;c().enabled=true;}if(b.id==2){int i=0;for(int n=0;n<SceneConfig.PALETTES.length;n++)if(SceneConfig.PALETTES[n].equals(c().palette))i=n;c().palette=SceneConfig.PALETTES[(i+1)%4];}if(b.id==3)legacy=!legacy;if(b.id==4)c().sky="Off";if(b.id==5){c().skySpeed=1;c().skyLiveliness=.6f;c().skyBreathing=1;c().palette="Alien";}AlienClient.get().save();initGui();}
    @Override public void drawContents(int x,int y,float p){Ui.background(width,height);Ui.text("ALIEN / LIVING SKY",14,14,Ui.theme().text);Ui.text(c().sky+" / "+SceneShaders.status(),14,29,Ui.theme().muted);super.drawContents(x,y,p);}
    private final class SkyCard extends Ui.Button{SkyCard(int id,int x,int y,int w,int h,String text){super(id,x,y,w,h,text);} @Override public void drawButton(net.minecraft.client.Minecraft m,int mx,int my){Ui.rounded(xPosition,yPosition,width,height,5,displayString.equals(c().sky)?Ui.accent():Ui.theme().surfaceRaised);int sky=0;for(int i=0;i<SceneConfig.SKIES.length;i++)if(SceneConfig.SKIES[i].equals(displayString))sky=i;SceneShaders.skyPreview(c(),sky,xPosition+2,yPosition+2,width-4,height-4,SceneSkyScreen.this.width,SceneSkyScreen.this.height);Ui.rounded(xPosition+2,yPosition+height-13,width-4,11,0,0xaa100e24);Ui.centered(displayString,xPosition+width/2f,yPosition+height-12,Ui.theme().text);}}
    @Override public void onGuiClosed(){AlienClient.get().save();}
}
